static int aie2_destroy_context_req(struct amdxdna_dev_hdl *ndev, u32 id)
{
	DECLARE_AIE2_MSG(destroy_ctx, MSG_OP_DESTROY_CONTEXT);
	struct amdxdna_dev *xdna = ndev->xdna;
	int ret;

	req.context_id = id;
	ret = aie2_send_mgmt_msg_wait(ndev, &msg);
